"use strict";
var DOJO_FL_LESSONS = [
  { id:"FL-01", mod:"Web Security", t:"Un renard, une quête : le dojo qui raconte des histoires", sub:"Présentation du dojo : 8 modules, 28 défis annoncés — Web Security (6), Cryptography (3), Hash Cracking (3), Exploitation (5), Reverse Engineering (2), Open Source Intelligence (3), Forensics (1), Miscellaneous (5).",
    read:["Fluffy’s Adventure est le dojo le plus singulier de la carte : un dojo communautaire entièrement narratif. Son héros, Fluffy, est un renard curieux qui part en quête pour devenir un « blue belt-er » — un hacker ceinture bleue. Chaque défi est une longue histoire en anglais, et la faille technique y est déguisée en métaphore : une vache qui répète tout ce qu’on lui dit, une machine qui ouvre les paquets sans regarder dedans, une souris bibliothécaire qui relie les livres avec un secret. Le travail du joueur commence par traduire la métaphore en concept.",
      "L’histoire est continue : les personnages et les lieux reviennent d’un module à l’autre. Pip, un protogen aux pattes lumineuses, devient le compagnon de Fluffy ; on croise aussi Bessie la vache, Mallow la souris bibliothécaire, Echo la chatte argentée, Pitch le crapaud, Roen et Ohce. Plusieurs modules sont des chaînes séquentielles : Miscellaneous 01 mène au 02 puis au 03, OSINT avance d’une fresque à des coordonnées puis à un dépôt, et le théâtre Tail Tale du module Web ouvre la salle des reflets du module Exploitation. Sauter un épisode, c’est perdre un maillon de l’histoire — et parfois de la technique.",
      "Les leçons qui suivent sont écrites dans le même esprit que le reste du Dojo : elles traduisent chaque métaphore en concept — injection de commande, extraction d’archive, dépassement d’entier, oracle de compression, attaque temporelle, OSINT, forensique, capabilities — sans recopier les histoires du site et sans donner de solution. Et comme toujours ici, ce qui n’a pas pu être lu sur le site est signalé à sa place : défis verrouillés, titres seuls, et un défi identifié par son nom mais sans description — Pawtomaton, en Reverse Engineering — qui reste « À venir »."],
    ex:{ type:"qcm", q:"Qu’est-ce qui distingue Fluffy’s Adventure des autres dojos du parcours ?",
      opts:["C’est le dojo le plus difficile du site", "Ses défis forment une histoire continue où chaque faille technique est déguisée en métaphore, avec des personnages et des lieux récurrents", "Il se joue entièrement sans terminal"], ok:1 },
    why:"Ni plus dur, ni sans terminal : ce dojo est un conte. La compétence qu’il entraîne en premier n’est pas une commande, c’est la lecture — repérer, sous une vache, une mare de goudron ou une presse à relier, le mécanisme technique que l’histoire met en scène. C’est une compétence d’analyste autant que d’attaquant : les vrais systèmes aussi racontent leurs failles en langage ordinaire avant de les montrer en code." },
  { id:"FL-02", mod:"Web Security", t:"Cowsay : quand répéter devient exécuter", sub:"Module Web Security, défi 01 : Cowsay — Bessie la vache répète tout ce qu’on lui dit, sans jamais peser un seul mot.",
    read:["Au bord d’un champ, Bessie la vache répète à voix haute tout ce qu’on lui souffle. Fluffy comprend le point faible de la scène : pour Bessie, il n’y a aucune différence entre « quelque chose à dire » et « quelque chose à faire ». Il lui souffle donc autre chose qu’une phrase — et la vieille barrière du champ s’ouvre. Le programme mis en scène est cowsay, un petit outil qui affiche le texte qu’on lui donne dans une bulle de bande dessinée.",
      "Le concept est l’injection de commande, la faille web la plus littérale qui soit : un programme transmet l’entrée de l’utilisateur à un shell, sans la filtrer. Tant que l’entrée est du texte, tout va bien ; mais un caractère de contrôle — le point-virgule est le plus célèbre — change de nature en route : ce qui était une donnée devient un séparateur, et ce qui suit devient une seconde commande, exécutée avec les droits du programme. La frontière entre données et instructions n’existe que si le programme la maintient.",
      "La défense tient en trois réflexes : ne jamais construire une commande shell en y collant une entrée extérieure ; si un programme externe est indispensable, l’appeler directement avec une liste d’arguments séparés, sans passer par un shell ; et valider l’entrée contre ce qu’elle est censée être — un nom, un nombre, un choix dans une liste — plutôt que contre ce qu’elle ne doit pas contenir. Bessie répétera toujours ce qu’on lui dit : c’est au programme de décider ce qui, dans ce qu’on lui dit, a le droit de devenir un ordre."],
    term:"texte à afficher ; commande en plus\n<span class=\"tdim\">Le point-virgule est un séparateur de commandes pour le shell. Dans une entrée non filtrée, il transforme une donnée en instruction : c’est la définition même de l’injection de commande.</span>",
    ex:{ type:"qcm", q:"Pourquoi le programme du défi finit-il par exécuter autre chose que le texte à afficher ?",
      opts:["Parce que cowsay contient un virus", "Parce que l’entrée utilisateur est transmise au shell sans filtrage : un caractère comme « ; » y devient un séparateur, et la suite est exécutée comme une seconde commande", "Parce que la vache connaît le mot de passe du champ"], ok:1 },
    why:"Données et commandes ne sont séparées que par le soin du programme. Quand l’entrée traverse un shell sans filtrage, les caractères de contrôle qu’elle contient sont interprétés comme de la syntaxe : le « ; » clôt la première commande et ouvre la suivante. Toute la faille tient dans ce passage — et toute la défense aussi : pas de shell intermédiaire, des arguments séparés, une entrée validée pour ce qu’elle doit être." },
  { id:"FL-03", mod:"Web Security", t:"Sticky Tar Pit : l’archive qui écrit où elle veut", sub:"Module Web Security, défi 02 : Sticky Tar Pit — la « Fluffy Unarchiver », une machine qui ouvre tous les paquets (.zip, .tar, .tgz, .tbz2) sans jamais demander ce qu’il y a dedans.",
    read:["Au fond des bois, une mare de goudron et une machine construite par Fluffy lui-même, un été de stage : la Fluffy Unarchiver. Elle accepte tous les formats d’archives courants et en étale le contenu sur la berge, sans jamais examiner ce qu’elle extrait. Fluffy fabrique alors son propre paquet : parmi des fichiers ordinaires, il glisse un élément qui n’est pas un fichier mais un pointeur — un lien symbolique qui prétend appartenir à la berge mais mène ailleurs, vers un creux scellé sous le goudron. La machine suit le pointeur à la lettre, et le contenu caché se retrouve exposé.",
      "Le concept est l’extraction d’archive non sécurisée, connue sous le nom de Zip Slip quand elle passe par des chemins en « ../ » : une archive n’est pas une boîte de fichiers, c’est une liste d’instructions d’écriture — des chemins, des liens, des permissions — fournies par celui qui l’a créée. Un extracteur qui fait confiance à ces chemins peut écrire hors du dossier de destination : un lien symbolique extrait d’abord, puis un fichier « à travers » ce lien, et l’écriture atterrit n’importe où le lien pointe.",
      "La défense est une discipline d’extraction : résoudre chaque chemin et vérifier qu’il reste dans le dossier de destination, refuser ou neutraliser les liens symboliques et les chemins absolus, et extraire avec les droits les plus faibles possible. La leçon dépasse les archives : tout format qui décrit où écrire — sauvegarde, paquet d’installation, import de données — est une entrée à valider, pas un ordre à suivre."],
    term:"archive → chemins + liens + fichiers\n<span class=\"tdim\">Une archive est une liste d’instructions d’écriture. Un lien symbolique suivi à la lettre fait écrire l’extracteur hors du dossier prévu : c’est la traversée par lien, cousine du Zip Slip.</span>",
    ex:{ type:"qcm", q:"Quel est le défaut de conception de la Fluffy Unarchiver ?",
      opts:["Elle ne sait pas ouvrir les fichiers .zip", "Elle fait confiance aux chemins contenus dans l’archive — liens symboliques compris — et peut donc écrire ou exposer des fichiers hors du dossier de destination", "Elle extrait les fichiers trop lentement"], ok:1 },
    why:"L’extracteur traite le contenu de l’archive comme des ordres fiables alors que ce sont des données fournies par l’expéditeur du paquet. Un lien symbolique extrait en premier redirige toutes les écritures suivantes. La parade : vérifier que chaque chemin résolu reste dans le dossier cible et ne jamais suivre aveuglément les liens d’une archive reçue." },
  { id:"FL-04", mod:"Web Security", t:"Le théâtre des 9 223 372 036 854 775 807 contes", sub:"Module Web Security, défi 05 : The Everlasting Tail Tale. Les défis 03 (Leaky Tar Pit) et 04 (Slippery Tar Pit) sont verrouillés sur le site — voir la lecture.",
    read:["Entre le défi 02 et celui-ci, le module compte deux défis verrouillés : Leaky Tar Pit et Slippery Tar Pit. Leur titre est visible, leur description est masquée sur le site — on ne peut donc rien en affirmer, sinon qu’ils appartiennent vraisemblablement à la même famille que Sticky Tar Pit, celle de l’extracteur d’archive. C’est une inférence tirée du titre et de la chaîne, signalée comme telle : elle n’est pas un contenu du site, et ces deux défis ne sont pas adaptés en leçons.",
      "Le défi 05 mène Fluffy au Tail Tale Theater, un vieux serveur de contes qui diffuse « The Complete Chronicles of Furry Folk » : pour débloquer la sagesse des Anciens, il faudrait regarder les 9 223 372 036 854 775 807 contes, un par un. Fluffy reconnaît ce nombre : c’est celui qui se trouve juste au bord de ce qu’un certain type de compteur peut contenir — un cran avant de manquer de place. Il doit exister un moyen d’atteindre les racines sans grimper chaque branche.",
      "Le concept est le dépassement d’entier (integer overflow). 9 223 372 036 854 775 807 est la valeur maximale d’un entier signé sur 64 bits (INT64_MAX) : un compteur de ce type, incrémenté une fois de trop, « déborde » — il repasse par le négatif ou par zéro selon le type, au lieu de s’arrêter sagement. Tout contrôle qui compare une position, un solde ou un nombre d’accès à une borne peut être trompé par ce rebouclage : la défense consiste à utiliser des types adaptés, à vérifier les bornes avant l’opération plutôt qu’après, et à traiter tout compteur atteignable par une entrée extérieure comme une surface d’attaque."],
    term:"9 223 372 036 854 775 807 = INT64_MAX\n<span class=\"tdim\">Le plus grand entier signé codable sur 64 bits. Un cran de plus, et le compteur déborde : c’est le rebouclage que le défi met en scène.</span>",
    ex:{ type:"qcm", q:"Que vaut le nombre de contes du Tail Tale Theater, et pourquoi compte-t-il ?",
      opts:["C’est un nombre choisi au hasard pour faire peur", "C’est la valeur maximale d’un entier signé 64 bits : faire déborder un compteur de ce type le fait reboucler, ce qui peut tromper les contrôles de bornes", "C’est le nombre exact de fichiers du serveur"], ok:1 },
    why:"Un compteur n’est pas un nombre abstrait : c’est une case de taille fixe. À INT64_MAX + 1, la valeur ne grandit plus, elle reboucle. Tout programme qui fait confiance à un compteur — progression, crédits, tentatives, index — sans vérifier la borne avant l’opération expose ce rebouclage. Reconnaître les grandes constantes limites (2³¹−1, 2³²−1, 2⁶³−1) au premier coup d’œil fait partie du métier." },
  { id:"FL-05", mod:"Web Security", t:"Pawpularity Contest : ce qu’un titre seul ne dit pas", sub:"Module Web Security, défi 06 : Pawpularity Contest — titre visible, aucune description sur la page du module.",
    read:["Le module Web Security se referme sur un défi dont on ne connaît que le titre : Pawpularity Contest. Aucune description n’apparaît sur la page — ni histoire, ni consigne, ni indice technique. Le titre évoque un concours de popularité, et l’on peut former une hypothèse — un vote ou un classement manipulable, par exemple — mais une hypothèse n’est pas un contenu : rien sur le site ne la confirme, et cette leçon ne la présentera pas comme un fait.",
      "Cette leçon-ci porte donc sur un geste du métier plutôt que sur une faille : distinguer, dans ce qu’on sait d’un système, le fait (le titre existe), l’inférence (la famille probable d’un défi verrouillé, déduite de sa chaîne) et l’inconnu (le mécanisme de ce défi-ci). En audit comme en réponse à incident, confondre les trois fabrique de faux rapports : on « sait » alors des choses que personne n’a vérifiées, et les décisions suivent.",
      "Le reste du dojo applique la même discipline : les défis verrouillés y sont signalés comme verrouillés, les thèmes seulement déduits d’un titre y sont marqués « inférés », et un défi — Reverse Engineering 02, Pawtomaton — reste « À venir » : identifié par son nom, mais sans description lisible sur le site. Les défis Cryptography 02 et 03, eux, ont été récupérés le 19 novembre 2026 et sont jouables ici (leçons FL-19 et FL-20). Pour connaître le vrai sujet de Pawpularity Contest, il faudra le jouer là-bas, sur pwn.college, quand son tour viendra dans l’histoire."],
    ex:{ type:"qcm", q:"Que peut-on affirmer du défi Pawpularity Contest à partir du site ?",
      opts:["C’est un défi de vote manipulable, c’est écrit dans sa description", "Seulement son titre : aucune description n’est publiée, donc son thème reste une hypothèse non confirmée", "Il est verrouillé comme les défis 03 et 04"], ok:1 },
    why:"Le titre est un fait ; le « concours de popularité manipulable » est une lecture du titre, pas une information du site. Et contrairement aux défis 03 et 04, celui-ci n’est même pas marqué verrouillé : sa description est simplement absente de la page. Savoir dire « on ne sait pas encore » — et l’écrire — est une compétence de sécurité à part entière." },
  { id:"FL-06", mod:"Cryptography", t:"The Folded Fable : le secret plié devant le message", sub:"Module Cryptography, défi 01 : The Folded Fable — Mallow la souris relie les histoires des voyageurs avec une presse à relier. Les défis 02 et 03 du module — OTPwned et Dam Breaker, récupérés le 19 novembre 2026 via l’API publique du site — sont couverts par les leçons FL-19 et FL-20.",
    read:["À la bibliothèque du tronc d’arbre, Mallow la souris relie les histoires des voyageurs. Avant chaque reliure, elle glisse devant les pages une « inscription de la bibliothèque », écrite à l’abri des regards — un texte secret que personne ne voit. En pliant, les phrases répétées disparaissent dans les plis, ne laissant que de petites boucles d’encre pour guider le dépliage ; une fois pressé, le livre est couvert de lignes sinueuses illisibles, scellé, et seule Mallow peut l’ouvrir. Fluffy, qui a passé son enfance à se demander ce qu’elle écrivait sur ces bandelettes, veut le découvrir avant la fermeture.",
      "Deux mécanismes techniques se cachent dans la métaphore. Le premier : un secret placé en préfixe, devant le message — c’est la construction des anciens codes d’authentification « à préfixe secret », dont la faiblesse célèbre est l’extension de longueur. Le second : la disparition observable des répétitions — c’est la compression, qui raccourcit d’autant plus que le texte contient de motifs déjà vus. Combinés, un secret préfixé et une compression dont le résultat se mesure forment la base des attaques dites par oracle de compression : la taille du livre relié renseigne sur son contenu.",
      "Les défis suivants du module ont depuis été récupérés (leçons FL-19 et FL-20) : Dam Breaker confirme la lecture « sceau prolongeable » — l’extension de longueur est bien l’un des mécanismes du module —, tandis qu’OTPwned ajoute un ingrédient absent de la fable : une clé lue à l’horloge. Pour la fable de Mallow elle-même, on ne tranchera toujours pas entre extension de longueur et oracle de compression : elle met les deux ingrédients en scène, et trancher sans son texte complet serait inventer. La défense générale, elle, est connue : ne jamais authentifier par un secret simplement préfixé (c’est le rôle des constructions HMAC), et ne jamais compresser puis chiffrer des données où un secret côtoie une entrée contrôlée par l’attaquant."],
    ex:{ type:"qcm", q:"Quels deux mécanismes la fable de Mallow met-elle en scène ?",
      opts:["Un mot de passe réutilisé et un réseau ouvert", "Un secret placé en préfixe du message, et une compression dont l’effet — la disparition des répétitions — reste observable de l’extérieur", "Un chiffrement par substitution et une clé perdue"], ok:1 },
    why:"La bandelette secrète glissée devant les pages, c’est le préfixe secret ; les phrases répétées qui s’effacent dans les plis, c’est la compression. Pris séparément, deux mécanismes anodins ; combinés, ils font fuiter le contenu par la taille du résultat — le principe des attaques par oracle de compression. Et la leçon reste volontairement ouverte pour la fable elle-même : Dam Breaker (leçon FL-20) confirme que l’extension de longueur est bien un mécanisme du module, mais rien ne dit que la fable de Mallow l’exploite plutôt que l’oracle de compression." },
  { id:"FL-19", mod:"Cryptography", t:"OTPwned : le masque jetable dont la clé se lit à l’horloge", sub:"Module Cryptography, défi 02 : OTPwned — Fluffy suit un fichier de test égaré jusque dans une partie du réseau sans panneau d’accueil, face à « The Encrypter », un petit terminal qui ne révèle que du texte verrouillé.",
    read:["Fluffy suit la trace d’un fichier de test égaré jusque dans un recoin du réseau où aucun panneau ne souhaite la bienvenue. Là, un petit terminal — The Encrypter — ne révèle que du texte verrouillé. Fluffy le sollicite plusieurs fois, vite : à chaque fois, exactement la même sortie. Il attend un peu, puis réessaie : cette fois, la sortie est complètement différente. Quelque chose a changé entre les deux séries de demandes — mais pas le fichier, et pas Fluffy.",
      "Le texte du défi le dit en clair : ce n’est pas une clé choisie qui protège le texte, c’est une horloge qui est lue. La clé est ce que l’horloge dit au moment où l’on demande — et une horloge, ça se lit aussi, par n’importe qui. Demander plusieurs fois dans le même instant donne la même clé, donc la même sortie ; attendre fait avancer l’horloge, donc change la clé, donc la sortie.",
      "Le concept est le masque jetable — one-time pad : un chiffrement par une clé aussi longue que le message, incassable à trois conditions strictes : la clé doit être vraiment aléatoire, rester secrète, et ne servir qu’une fois. Une clé dérivée d’une horloge ne remplit aucune de ces conditions : elle est prévisible pour qui peut lire la même horloge. La défense suit : une clé vraiment aléatoire, jamais réutilisée, et jamais dérivée d’une valeur observable — l’heure, un compteur, un identifiant public."],
    term:"demandes rapides, même instant → même sortie\naprès une attente → sortie entièrement différente\n<span class=\"tdim\">Si la clé dépend de l’horloge, celui qui lit l’horloge prédit la clé. Un masque jetable n’est incassable que si sa clé est vraiment aléatoire.</span>",
    ex:{ type:"qcm", q:"Pourquoi les demandes rapides donnent-elles toutes la même sortie, puis une sortie différente après une attente ?",
      opts:["Parce que le terminal se fatigue et change de clé au hasard", "Parce que la clé est lue à l’horloge : dans le même instant, l’horloge dit la même chose et la clé ne change pas ; après une attente, elle a avancé, et la clé — donc la sortie — change", "Parce que le fichier de test a été déplacé entre-temps"], ok:1 },
    why:"Le comportement observable raconte le mécanisme : sortie constante à instant constant, sortie nouvelle après un délai — la variable cachée est le temps. Un masque jetable tire toute sa force d’une clé imprévisible ; une clé qui se lit sur une horloge publique est prévisible par construction. C’est la différence entre « aléatoire » et « qui change » : changer ne suffit pas, il faut que personne ne puisse prévoir la prochaine valeur." },
  { id:"FL-20", mod:"Cryptography", t:"Dam Breaker : le sceau qu’on peut prolonger", sub:"Module Cryptography, défi 03 : Dam Breaker — au barrage de « The B34ver Trust Digital Security Dam », chaque commande exige un « sceau » d’approbation ; Roen le castor, ingénieur en chef, remet à Fluffy un identifiant invité — un sceau de confiance limitée, pour une visite supervisée.",
    read:["Le barrage de The B34ver Trust est gardé par Roen le castor, son ingénieur en chef. Aucune commande du système de contrôle ne s’exécute sans un « sceau » d’approbation, vérifié contre un secret que seul Roen connaît. Roen remet à Fluffy un identifiant invité : un sceau authentique, mais de confiance limitée — de quoi faire une visite supervisée, rien de plus. Fluffy se dit qu’avec une bonne compréhension de la façon dont les sceaux sont fabriqués, un sceau limité pourrait être étendu plus loin que Roen ne l’imagine.",
      "Le concept est l’authentification des messages — le sceau, ou MAC : une empreinte calculée à partir d’un secret et du message, qui prouve que le message a été approuvé par le détenteur du secret, sans révéler le secret. Mais une construction naïve — l’empreinte du secret et du message simplement collés l’un à l’autre — a une faiblesse célèbre : elle peut être prolongée. À partir d’un sceau valide pour un message, on peut fabriquer le sceau d’un message plus long qui commence par le premier — sans connaître le secret. C’est l’attaque par extension de longueur.",
      "Ce défi confirme la lecture « sceau prolongeable » déjà évoquée dans la leçon FL-06 à propos de la fable de Mallow : le secret placé devant le message y trouvait ici son application directe. La défense est la raison d’être des constructions sérieuses d’authentification — HMAC, conçue pour qu’aucune extension de ce type ne soit possible : un sceau ne doit jamais être une simple empreinte de secret collé, quelle que soit la solidité de la fonction d’empreinte."],
    ex:{ type:"qcm", q:"Que permet l’attaque par extension de longueur contre un sceau naïf, sans connaître le secret de Roen ?",
      opts:["De retrouver le secret à partir du sceau invité", "De prolonger un sceau valide pour couvrir un message plus long commençant par le message d’origine : le sceau limité peut ainsi être étendu au-delà de ce que son émetteur avait approuvé", "De casser la fonction d’empreinte elle-même"], ok:1 },
    why:"Ni le secret ni la fonction d’empreinte ne sont attaqués : c’est la construction qui est fautive. Coller secret et message dans une empreinte laisse la porte ouverte à l’extension — on continue le calcul là où le sceau légitime s’était arrêté. HMAC existe précisément pour fermer cette porte : authentifier n’est pas « hacher avec un secret », c’est utiliser une construction pensée pour ce rôle." },
  { id:"FL-07", mod:"Hash Cracking", t:"Des cookies tamponnés : le hash ne se déchiffre pas, il se devine", sub:"Module Hash Cracking, défis 01 et 02 : Hashi Munch, puis Cat Whisperer — Echo, la chatte argentée qui retrouve les originaux dans des piles de bruit. Le défi 02 est signé « Suvoni » (l3ak.team).",
    read:["Dans le coffre, le terminal de l’« Encrypter™ » distribue un paquet de cookies en papier ciré, chacun tamponné d’une longue suite de caractères irréguliers : quelque chose de réel, transformé par un processus en une forme illisible. Fluffy comprend qu’il s’agit d’empreintes — des hashes — et qu’il n’a pas le vocabulaire pour ce travail. Il part chercher une chatte argentée réputée pour retrouver les originaux dans des piles de bruit : Echo.",
      "Echo étale les séquences sur la table et donne la leçon du module : « Ce ne sont pas des difficiles. Des phrases courantes. Des motifs prévisibles. Le hash cède quand on essaie la bonne supposition. » Une fonction de hachage est à sens unique : on ne peut pas l’inverser, pas « déchiffrer » une empreinte. Mais on peut hacher des candidats — mots du dictionnaire, phrases courantes, variantes avec chiffres et majuscules — et comparer les empreintes obtenues à celle qu’on cherche. Quand le mot de passe d’origine est une phrase courante, il finit par apparaître dans la liste des essais : c’est l’attaque par dictionnaire.",
      "La portée dépasse le dojo : les bases de mots de passe qui fuient sont attaquées exactement ainsi, à grande échelle, avec des listes de candidats raffinées par des années de fuites précédentes. Ce qui protège un compte n’est pas la complexité décorative — une majuscule et un chiffre à la fin — mais l’imprévisibilité réelle : une phrase de passe longue et unique, qu’aucun dictionnaire ne contient parce qu’elle n’a jamais servi ailleurs."],
    ex:{ type:"qcm", q:"Comment retrouve-t-on l’original d’une empreinte de mot de passe faible ?",
      opts:["En inversant la fonction de hachage, qui est réversible si on connaît l’algorithme", "En hachant des candidats — dictionnaires, phrases courantes, variantes — et en comparant les empreintes : on ne déchiffre jamais le hash, on devine l’entrée", "En demandant l’original au serveur, qui le conserve"], ok:1 },
    why:"Un hash est conçu pour être à sens unique : aucune opération ne remonte de l’empreinte au mot de passe. Le cassage est donc une recherche, pas un calcul inverse — et il ne réussit que si le secret figure dans l’espace des candidats essayés. D’où la force des phrases de passe longues, uniques et jamais réutilisées : elles ne sont dans aucun dictionnaire." },
  { id:"FL-08", mod:"Hash Cracking", t:"Fox Whisperer : les empreintes difficiles, et la défense qui les protège", sub:"Module Hash Cracking, défi 03 : Fox Whisperer — verrouillé sur le site, description masquée ; Echo annonçait à la fin du défi 02 une rencontre « pour les plus difficiles ».",
    read:["Le module se referme sur un défi verrouillé : Fox Whisperer. Le titre est visible, la description est masquée — on ne peut donc pas en décrire le contenu. On peut seulement noter la promesse faite par Echo à la fin du défi précédent : elle envoyait Fluffy à la taverne rencontrer quelqu’un d’autre « pour les plus difficiles ». Le thème probable — des empreintes plus dures à casser que les phrases courantes du défi 02 — est une inférence de cette phrase et du titre, signalée comme telle, pas un contenu lu sur le site.",
      "Cette leçon prend donc le parti de la défense : qu’est-ce qui rend un mot de passe stocké réellement difficile à casser, même quand la base d’empreintes a fuité ? D’abord le sel : une valeur aléatoire unique par compte, mélangée avant le hachage, qui rend les pré-calculs inutiles — deux comptes avec le même mot de passe n’ont plus la même empreinte, et aucune table préparée à l’avance ne sert. Ensuite la lenteur voulue : des fonctions de dérivation coûteuses et réglables — bcrypt, scrypt, Argon2 — qui font payer chaque essai en temps et en mémoire. Un dictionnaire d’un milliard de candidats cesse d’être une formalité quand chaque candidat coûte une fraction de seconde et des mégaoctets.",
      "Côté utilisateur, la même logique : la longueur bat la décoration. Une phrase de passe de cinq mots sans rapport vaut mieux qu’un mot de huit caractères « complexifié » de façon prévisible — les règles de complexité prévisibles font partie des motifs qu’Echo essaie en premier. Et côté système : limiter les tentatives en ligne, surveiller les fuites de bases, et ne jamais stocker un mot de passe avec un hash rapide conçu pour la vitesse — MD5 et SHA-1 sont des fonctions de contrôle d’intégrité, pas des coffres."],
    ex:{ type:"qcm", q:"Qu’est-ce qui rend une base d’empreintes fuie réellement coûteuse à casser ?",
      opts:["Le fait de renommer la table des utilisateurs", "Un sel unique par compte, qui tue les pré-calculs, combiné à une fonction de hachage lente et coûteuse (bcrypt, scrypt, Argon2), qui fait payer chaque essai", "Un mot de passe administrateur très long sur le serveur"], ok:1 },
    why:"Le cassage est une économie : l’attaquant compare le coût des essais au gain. Le sel unique détruit la mutualisation (chaque compte devient un problème séparé, les tables pré-calculées ne servent plus), et une fonction lente multiplie le prix de chaque candidat. Renommer une table ne change ni l’un ni l’autre : la sécurité du stockage tient aux mathématiques du hachage, pas à la discrétion des noms." },
  { id:"FL-09", mod:"Exploitation", t:"Temporal Tails : le PIN qui fuit par le temps", sub:"Module Exploitation, défi 01 : Temporal Tails — une seconde porte, un clavier, un code PIN administrateur, aucun indice, aucun nombre d’essais indiqué.",
    read:["Après avoir passé la porte principale avec un faux laissez-passer — le sceau de Roen —, Fluffy trouve une seconde porte, plus lourde : un clavier, un code PIN administrateur à saisir, sans indice ni compteur d’essais. Les refus arrivent vite. Sauf que certains chiffres font réfléchir le clavier un peu plus longtemps avant de refuser. Pas du hasard : une fraction de seconde, régulière, répétable. Le PIN n’est pas lisible — mais le temps de vérification de chaque chiffre, lui, se mesure.",
      "Le concept est l’attaque par canal temporel (timing attack). Elle naît d’une optimisation en apparence innocente : comparer un secret caractère par caractère en s’arrêtant au premier caractère faux. Réponse fausse dès le premier chiffre : refus immédiat. Premier chiffre juste, second faux : la comparaison fait un pas de plus, et le refus prend un peu plus de temps. En mesurant ces durées sur de nombreux essais, on reconstruit le secret position par position — chaque chiffre correct se trahit par le délai qu’il ajoute. L’information ne sort ni par l’écran ni par un message d’erreur : elle sort par l’horloge.",
      "La défense est connue mais doit être délibérée : comparer en temps constant — examiner toujours tous les caractères, accumuler le résultat, ne répondre qu’à la fin — et ne jamais laisser une comparaison de secret court-circuiter. Le même principe protège les jetons d’API, les codes de vérification et les signatures : partout où un secret est comparé, la durée de la réponse est un canal, et il se ferme en rendant cette durée indépendante du contenu."],
    term:"réponse(1xxx) : 2 ms · réponse(4xxx) : 2 ms · réponse(47xx) : 5 ms\n<span class=\"tdim\">Le délai grandit quand un chiffre de plus est juste : la comparaison s’arrête au premier faux, et l’horloge raconte où elle s’est arrêtée.</span>",
    ex:{ type:"qcm", q:"Comment un code PIN peut-il fuiter alors qu’aucune réponse n’affiche jamais le moindre chiffre ?",
      opts:["Le clavier affiche le PIN en très petits caractères", "La vérification s’arrête au premier chiffre faux : le temps de réponse révèle combien de chiffres initiaux sont justes, et le secret se reconstruit chiffre par chiffre", "Le PIN est caché dans le bruit du clavier"], ok:1 },
    why:"C’est un canal auxiliaire : l’information ne passe pas par le contenu des réponses, toutes identiques (« refusé »), mais par leur durée. Une comparaison qui court-circuite au premier caractère faux transforme chaque position du secret en une question mesurable. La parade — comparer en temps constant, sur toute la longueur, quel que soit le résultat — supprime le canal en rendant la durée indépendante du secret." },
  { id:"FL-10", mod:"Exploitation", t:"La Salle des Reflets Infinis : jouer contre toutes les variantes", sub:"Module Exploitation, défi 02 : Threefold, Infinite Reflections — après le dernier conte du Tail Tale Theater, une porte cachée ouvre sur la Salle des Reflets Infinis.",
    read:["Après le dernier conte du Tail Tale Theater — le défi Web 05 —, une porte cachée s’ouvre vers la Salle des Reflets Infinis : une table de marbre avec neuf cases éternelles, et une plaque : « Tic Toc Tou — Play for the Moment ». Quand Fluffy tend la main vers le plateau, ses reflets tendent aussi la leur — certains en avance, d’autres en retard. Chaque coup se multiplie en variations infinies, aucune certaine, aucune sûre. Neuf cases, deux joueurs, aucune information cachée : c’est un morpion.",
      "Le thème technique de ce défi n’est pas écrit en toutes lettres dans sa description : il est inféré de la scène, et signalé comme tel. Un jeu à information parfaite sur un plateau 3×3, face à un adversaire dont les « reflets » explorent les coups en avance et en retard, évoque la théorie des jeux et la recherche arborescente : représenter toutes les suites de coups possibles comme un arbre, et évaluer chaque position en supposant que l’adversaire choisira, à chaque étage, le coup qui t’est le plus défavorable — l’algorithme minimax. Sur un morpion, l’arbre entier tient en mémoire : la partie « parfaite » est calculable, et elle se termine toujours par un match nul entre joueurs parfaits.",
      "Que le défi attende une exploration de l’arbre de jeu ou une faille dans les règles de la salle, la lecture défensive est la même : un système dont toutes les variantes sont énumérables peut être « résolu » par énumération — c’est vrai d’un plateau de morpion, d’un protocole à peu d’états, ou d’un espace de mots de passe trop petit. La taille de l’espace des possibles est un paramètre de sécurité : en dessous d’un certain seuil, l’exhaustivité remplace l’ingéniosité."],
    ex:{ type:"qcm", q:"Face à un jeu à information parfaite comme le morpion, que fait une stratégie de type minimax ?",
      opts:["Elle joue des coups au hasard pour rester imprévisible", "Elle explore l’arbre des coups possibles et choisit le coup qui maximise ton résultat en supposant que l’adversaire, lui, choisira toujours le coup qui le minimise", "Elle mémorise les parties des autres joueurs"], ok:1 },
    why:"Neuf cases, aucune information cachée : toutes les suites sont énumérables, donc calculables. Le minimax évalue chaque position du point de vue des deux camps à la fois — je choisis le meilleur pour moi, en sachant que tu choisiras le pire pour moi. C’est le thème inféré de la Salle des Reflets : des reflets « en avance » qui explorent les variantes. Et la leçon déborde du jeu : tout espace de possibilités assez petit pour être énuméré peut être traversé exhaustivement." },
  { id:"FL-11", mod:"Exploitation", t:"The Final Commission : le combat conçu pour ne pas être gagné", sub:"Module Exploitation, défi 03 : The Final Commission. Les défis 04 (Morning on the Windowsill) et 05 (Phantom Paws) n’ont que leur titre sur la page — thèmes inconnus, signalés dans la lecture.",
    read:["Fluffy ouvre un jeu de donjon non répertorié, sans auteur. La liste des recrues reprend les visages connus de la quête : Bessie, Roen, Echo et Ohce, Pip en « Companion », et lui-même en tête. Il ne peut pas combattre — seulement recruter. Il les envoie dans tous les ordres contre le Gardien du fond du donjon, une figure manifestement conçue pour ne pas tomber : à chaque fois, dès que le Gardien joue son tour, c’en est fini d’eux. Dans un coin du dernier étage, un marchand : une seule relique en stock, inachevée, sans nom gravé. Prix : 1337 pièces d’or.",
      "Le concept général est l’exploitation de la logique d’un jeu : quand l’affrontement direct est conçu comme impossible, la faille ne se trouve pas dans la force des personnages mais dans les règles elles-mêmes — l’économie (comment gagner ou dépenser les 1337 pièces), le recrutement (ce qu’un ordre ou une composition change), ou un objet au rôle inattendu. Le mécanisme exact du défi n’est pas confirmé par sa description, et cette leçon ne l’inventera pas : retenir la posture — lire les règles comme une surface d’attaque — plutôt qu’une recette.",
      "Le module Exploitation compte encore deux défis, Morning on the Windowsill et Phantom Paws, dont seule le titre apparaît sur la page : aucune description, donc aucun thème affirmé ici — ils sont signalés comme inconnus, comme Pawpularity Contest côté web. Dans les vrais jeux comme dans les applications, la « logique métier » est une surface d’attaque à part entière : prix manipulables, ordre des opérations, conditions de victoire contournables sans jamais toucher au code de bas niveau. Les gardes-fous sont du même ordre : vérifier côté serveur chaque règle que le client affiche, et traiter toute économie interne — monnaie, points, inventaire — comme une donnée sensible."],
    ex:{ type:"qcm", q:"Face à un Gardien « conçu pour ne pas tomber » en combat direct, où la posture d’exploitation cherche-t-elle la faille ?",
      opts:["Dans des personnages plus forts, en rejouant jusqu’à avoir de la chance", "Dans la logique du jeu lui-même — économie, recrutement, règles, objets — plutôt que dans l’affrontement : le mécanisme exact reste à découvrir en jouant", "Dans le code source du dojo, publié avec le défi"], ok:1 },
    why:"Aucun ordre d’envoi ne change l’issue du combat : c’est le signal que la solution n’est pas dans le combat. La relique à 1337 pièces et le marchand existent dans l’histoire pour une raison — mais laquelle, exactement, la description ne le dit pas, et cette leçon ne tranche pas. La posture, elle, est générale : quand la voie frontale est fermée par construction, ce sont les règles du système qui deviennent la surface à examiner." },
  { id:"FL-12", mod:"Reverse Engineering", t:"Clumsy Paw Syntax : la machine qui ne comprend que trois nombres", sub:"Module Reverse Engineering, défi 01 : Clumsy Paw Syntax — flashback : Fluffy, encore jeune, traîne un vieux terminal dans une clairière secrète, où un protogen est déjà là : Pip. Le défi 02 du module est désormais identifié — Pawtomaton — mais sa description est vide sur le site : il reste « À venir », sans contenu inventé.",
    read:["Flashback. Fluffy, encore jeune, a traîné pièce par pièce un vieux terminal dans une clairière secrète. Un protogen est déjà là — Pip, pattes lumineuses, visière bleu électrique. La machine est étrange : elle ne comprend que trois nombres à la fois. Fluffy se met à taper, maladroitement : le code plante deux fois, donne une mauvaise réponse une troisième fois ; il corrige, et le programme finit par tourner — petit, brouillon, entièrement à lui. « Je continuerai, même s’il faut cent essais. — Moi aussi », répond Pip. C’est ici que le compagnon de toute la quête entre dans l’histoire.",
      "Le concept est la programmation au plus près de la machine : un jeu d’instructions minimal, où chaque opération s’écrit avec au plus trois nombres — typiquement une destination et deux sources, ou une opération et ses opérandes. C’est la forme des vraies instructions assembleur, dépouillée de tout confort : pas de variables nommées, pas d’expressions composées, seulement des opérations élémentaires enchaînées. Raisonner ainsi — décomposer un calcul en pas que la machine peut exécuter un par un — est le socle de la rétro-ingénierie : lire un programme compilé, c’est retrouver, dans ces pas élémentaires, le calcul d’origine.",
      "La page du module ne rend que la description de ce défi 01 : le défi 02 de Reverse Engineering est désormais identifié par son nom — Pawtomaton — mais sa description est vide sur le site : il reste donc « À venir », identifié par son nom, sans contenu lisible ni inventé. Retiens aussi la méthode du jeune Fluffy, car c’est celle du module entier : essayer, planter, lire l’erreur, corriger. La rétro-ingénierie n’avance pas autrement — cent essais s’il le faut."],
    ex:{ type:"qcm", q:"Qu’évoque une machine qui « ne comprend que trois nombres à la fois » ?",
      opts:["Un clavier dont seules trois touches fonctionnent", "Un jeu d’instructions minimal où chaque opération prend au plus trois opérandes — programmer au plus près de la machine, en pas élémentaires", "Un code PIN à trois chiffres"], ok:1 },
    why:"Trois nombres par instruction : c’est la silhouette des opérations assembleur (une destination, deux sources) réduite à l’essentiel. Ce défi d’ouverture de module n’apprend pas encore à lire un binaire inconnu ; il apprend à penser comme la machine qui l’exécutera — décomposer, enchaîner, corriger. C’est le premier geste de toute rétro-ingénierie, et la scène où Fluffy rencontre Pip, le compagnon des modules suivants." },
  { id:"FL-13", mod:"Open Source Intelligence", t:"De la fresque au dépôt : suivre une piste en sources ouvertes", sub:"Module Open Source Intelligence, défis 01 et 02 : Beyond the Veil, puis The Cyber Paws — une chaîne séquentielle : une fresque, des coordonnées, un nom.",
    read:["Premier temps de la chaîne OSINT. Dans un pavillon plus grand dedans que dehors, les murs sont couverts d’art superposé, tags sur tags, fresques sur fresques anciennes. Une pièce se distingue : une figure aux pattes lumineuses et au visage lumineux, peinte en pleine marche — et en dessous, en petits traits délibérés, une série de coordonnées. Fluffy reconnaît la qualité du trait, la patience du pinceau, sans encore pouvoir nommer l’auteur. Les coordonnées pointent vers le nord. C’est le geste de base de l’OSINT visuel : une œuvre publique contient des données — ici une géolocalisation écrite en clair, pour qui sait regarder.",
      "Deuxième temps : les coordonnées mènent sur un campus de vieux bâtiments de brique, jusqu’à une seconde marque sur un mur entre deux arbres — la même figure, en pleine foulée, une bulle « beep boop », de nouvelles coordonnées. Cette fois, Fluffy reconnaît le style : un seul protogen peint comme ça. Pip. En dessous, plus petit, dans la même écriture soignée : un nom. Pas un lieu — un dépôt. L’attribution par le style — reconnaître un auteur à sa signature visuelle avant même de lire son nom — est une technique OSINT réelle : les artefacts publics portent la marque de leurs auteurs, et les recoupements entre artefacts font avancer la piste.",
      "La discipline de la chaîne vaut pour toute investigation en sources ouvertes : chaque indice est relevé tel quel (les coordonnées sont copiées, pas interprétées), chaque étape s’appuie sur la précédente sans la devancer, et l’identification d’un auteur vient du recoupement — style, lieux, écriture — jamais d’une intuition seule. La troisième étape de la chaîne, le dépôt lui-même, fait l’objet de la leçon suivante."],
    ex:{ type:"order", q:"Remets dans l’ordre la piste suivie par Fluffy dans les deux premiers défis OSINT :",
      items:["Observer la fresque du pavillon et relever les coordonnées dissimulées sous la figure", "Suivre les coordonnées vers le nord, jusqu’au campus de briques", "Reconnaître l’auteur à son style — Pip — et lire le nom laissé sous la seconde marque", "Comprendre que le nom désigne un dépôt, pas un lieu : la piste change de nature"],
      disp:[1,3,0,2] },
    why:"La chaîne est strictement séquentielle : la fresque donne un lieu, le lieu donne une seconde marque, la marque donne un auteur et un nom, le nom ouvre le troisième défi. Sauter une étape — chercher le dépôt avant d’avoir reconnu le style, par exemple — n’a aucun point d’appui. C’est la forme de toute piste OSINT : des artefacts publics, relevés dans l’ordre, qui se répondent." },
  { id:"FL-14", mod:"Open Source Intelligence", t:"Nostalgic Commits : l’historique nettoyé n’est pas l’histoire", sub:"Module Open Source Intelligence, défi 03 : Nostalgic Commits — le nom laissé par Pip mène au journal de Fluffy, « Fluffy’s Diary », un dépôt dont la page du défi donne le lien (dépôt GitHub, non reproduit ici).",
    read:["Le nom laissé par Pip mène Fluffy à un dépôt qu’il n’avait pas revu depuis des années : son propre journal, « Fluffy’s Diary ». L’historique semble propre : trois commits, nets, séquentiels, rien d’anormal. Sauf que Fluffy se souvient avoir écrit davantage. L’historique n’est pas toute l’histoire : c’est la version que quelqu’un a décidé de laisser visible. Ce qui s’y trouvait avant est toujours quelque part — si l’on sait où chercher.",
      "Le concept est l’OSINT sur dépôt git. Réécrire ou « nettoyer » un historique — écraser des commits, réécrire des branches — déplace les pointeurs, mais les anciens objets du dépôt ne disparaissent pas aussitôt : commits devenus orphelins, anciennes révisions encore présentes dans la base d’objets, journaux de références (reflog) côté local, et copies chez tous ceux qui ont cloné ou forké avant le nettoyage. Sur un dépôt public, la suppression est donc une intention, pas un fait : ce qui a été poussé doit être considéré comme publié pour toujours.",
      "La leçon de défense est l’une des plus concrètes du dojo : ne jamais commiter un secret — clé d’API, mot de passe, jeton — même « pour le retirer juste après ». La bonne réponse à un secret commité n’est pas de réécrire l’historique mais de révoquer le secret, car des copies de l’ancienne version peuvent exister n’importe où. Et côté investigation, le réflexe miroir : devant un historique trop propre, chercher ce que la propreté a coûté — les objets sans référence racontent souvent l’histoire d’avant."],
    term:"historique visible : 3 commits, nets\n<span class=\"tdim\">Un historique réécrit déplace les pointeurs ; les anciens objets, eux, restent souvent dans le dépôt. « Supprimé de l’historique » ne veut pas dire « supprimé ».</span>",
    ex:{ type:"qcm", q:"Pourquoi un historique git « nettoyé » ne garantit-il pas que les anciennes données ont disparu ?",
      opts:["Parce que git refuse de réécrire un historique", "Parce que les objets devenus orphelins et les anciennes révisions restent souvent présents dans le dépôt — et des copies existent chez quiconque a cloné avant le nettoyage", "Parce que le journal de Fluffy est hébergé sur un serveur sans sauvegarde"], ok:1 },
    why:"La réécriture change ce que l’historique montre, pas nécessairement ce que le dépôt contient : objets non référencés, reflog, forks et clones conservent l’« avant ». C’est pour cela qu’un secret commité se traite par révocation, jamais par simple nettoyage — et qu’un enquêteur OSINT lit un dépôt en commençant par ce que son historique ne montre plus." },
  { id:"FL-15", mod:"Forensics", t:"The Clumsy Typist : ce que le câble a entendu", sub:"Module Forensics, défi unique : The Clumsy Typist — dans un couloir poussiéreux, un terminal abandonné garde ses journaux, dont une capture de paquets : du trafic clavier.",
    read:["Le module Forensics ne compte qu’un défi, et il est d’une précision redoutable. Dans un dossier près de la racine d’un terminal abandonné : une capture de paquets — du trafic clavier. Quelqu’un a tapé ici, maladroitement, avec beaucoup de corrections, des mots défaits et refaits en cours de frappe. Chaque frappe a été capturée, chaque correction aussi. La phrase du défi résume toute la forensique : « Le câble ne sait pas ce que tu voulais taper, seulement ce que tu as fait. »",
      "Le concept est l’analyse d’une capture réseau (pcap) de frappes clavier — typiquement le trafic USB HID d’un clavier, où chaque paquet décrit l’état des touches à un instant. Reconstituer le texte ne consiste pas à lire les caractères dans l’ordre des paquets : il faut rejouer la frappe. Les touches de correction — retour arrière surtout — font partie du flux : un mot suivi de trois retours arrière puis d’un autre mot donne un texte final différent de la simple concaténation. L’analyste reconstruit donc le document tel qu’il existait à l’écran à la fin, en appliquant chaque frappe et chaque effacement, dans l’ordre.",
      "La portée dépasse l’exercice : les enregistreurs de frappe (keyloggers) et les captures de trafic d’entrée sont des sources de preuve réelles en investigation — et des vecteurs d’espionnage réels en attaque, puisqu’un flux de frappes contient mots de passe et messages « jamais envoyés » compris, corrections incluses. Côté défense : ce qui transite en clair sur un câble ou un réseau peut être relu ; les frappes ne font pas exception."],
    ex:{ type:"qcm", q:"Que contient exactement une capture de trafic clavier, et comment en tire-t-on le texte final ?",
      opts:["Le texte final uniquement, tel qu’il s’affichait à l’écran", "Chaque frappe telle qu’elle a eu lieu — erreurs et corrections comprises : le texte se reconstruit en rejouant la frappe, retours arrière inclus", "Seuls les mots de passe, que le clavier marque spécialement"], ok:1 },
    why:"Une capture ne contient pas un document, elle contient des événements : telle touche enfoncée, telle touche relâchée, tel retour arrière. Le texte final est une reconstruction — on applique les événements dans l’ordre, en tenant les corrections pour ce qu’elles sont : des modifications du texte en cours. C’est le geste de base de l’analyse forensique d’une capture, et la raison pour laquelle ces flux sont à la fois des preuves précieuses et des données sensibles." },
  { id:"FL-16", mod:"Miscellaneous", t:"Rune of 91 et Woof Dot Dash : deux écritures pour un signal", sub:"Module Miscellaneous, défis 01 et 02 : Rune of 91, puis Woof Dot Dash — le début d’une chaîne séquentielle en trois temps (01 → 02 → 03).",
    read:["Le module Miscellaneous s’ouvre sur une chaîne de trois défis liés. Premier temps : le parchemin laissé par Ohce mène Fluffy plus profond dans la forêt. Déplié au clair de lune : une écriture inconnue, symboles serrés, lettres, chiffres et marques étranges. « Pas une base que j’aie jamais apprise. » Quatre-vingt-onze caractères distincts couvrent le parchemin — tout un alphabet qui n’en est pas tout à fait un. Il faudra apprendre à le lire avant de comprendre le message. Le concept est l’encodage base91 : comme base64, il transforme des données binaires en texte, mais son alphabet de 91 caractères le rend plus dense — moins de caractères pour le même contenu.",
      "Deuxième temps : les 91 glyphes décodés donnent des coordonnées. Fluffy les suit jusqu’à une clairière où une tablette de pierre porte deux écritures parallèles gravées côte à côte — une pierre de Rosette. Puis un signal, faible, rythmique : des rafales courtes et longues, des pauses porteuses de sens. « Point et tiret. » Le signal est du code Morse ; mais il ne prend tout son sens que dans les deux écritures à la fois : la table de correspondance bilingue de la tablette sert de clé de lecture au signal décodé.",
      "La leçon d’ensemble : un encodage n’est pas un chiffrement. Base91, base64, Morse — rien n’y est secret : ce sont des alphabets publics, et quiconque connaît l’alphabet relit le message. Reconnaître un encodage à son alphabet — compter les caractères distincts est le premier indice — puis enchaîner les décodages couche par couche, est un réflexe de base en CTF comme en analyse : les données « illisibles » sont souvent simplement écrites dans une autre notation."],
    ex:{ type:"qcm", q:"Comment reconnaît-on un texte en base91, et en quoi diffère-t-il d’un chiffrement ?",
      opts:["À sa longueur, toujours un multiple de 91 ; et c’est un chiffrement faible", "À son alphabet de 91 caractères distincts — et ce n’est qu’un encodage : un alphabet public, sans secret, que quiconque peut relire", "Aux chiffres romains qu’il contient"], ok:1 },
    why:"Le nombre de caractères distincts est la signature d’un encodage : 64 pour base64, 91 pour base91. Mais ni l’un ni l’autre ne protège quoi que ce soit : encoder, c’est réécrire ; chiffrer, c’est rendre illisible sans la clé. Confondre les deux — croire des données « protégées » parce qu’elles sont en base64 — est une erreur classique que cette chaîne de défis démonte patte après patte." },
  { id:"FL-17", mod:"Miscellaneous", t:"Fivefold Tails : cinq copies abîmées valent un original", sub:"Module Miscellaneous, défi 03 : Fivefold Tails — le signal de la leçon précédente arrive en cinq exemplaires, chacun endommagé à des endroits différents.",
    read:["Troisième temps de la chaîne. Le signal n’est pas propre : il arrive en cinq exemplaires — la même transmission répétée cinq fois, chacune endommagée à des endroits différents. Des sections entières manquent, remplacées par du bruit, comme des pages arrachées d’un livre, mais arrachées différemment dans chaque copie. Fluffy les étale côte à côte : ce qui manque dans l’une est intact dans une autre. Le travail n’est pas mathématique, c’est de la comparaison et de la patience — reconstituer le signal section par section en croisant les copies.",
      "Le concept est la reconstruction par redondance, le principe qui fonde la correction d’erreurs : si les dégâts ne tombent pas aux mêmes endroits, l’ensemble des copies contient l’original entier. Section par section, la version intacte — ou la version majoritaire, quand les copies divergent — fait foi. C’est exactement le mécanisme des codes correcteurs d’erreurs, du RAID qui reconstruit un disque mort depuis ses frères, des sauvegardes multiples, et, dans une forme raffinée, du partage de secret où un seuil de fragments suffit à reconstituer le tout.",
      "La condition du miracle est facile à rater : l’indépendance des dégâts. Cinq copies endommagées au même endroit ne valent pas mieux qu’une — la redondance ne protège que contre des pannes indépendantes. C’est la question à poser à toute stratégie de sauvegarde ou de réplication : les copies partagent-elles un point de défaillance commun — même salle, même support, même rançongiciel — ou leurs destins sont-ils réellement séparés ? La leçon suivante referme le module, et le dojo entier, sur le défi final."],
    ex:{ type:"qcm", q:"Pourquoi cinq copies endommagées d’un même signal permettent-elles de reconstituer l’original ?",
      opts:["Parce que cinq est un nombre premier", "Parce que les dégâts tombent à des endroits différents selon les copies : chaque section est intacte dans au moins l’une d’elles, et le recoupement reconstruit le tout", "Parce que le bruit s’annule toujours quand on additionne les signaux"], ok:1 },
    why:"La redondance ne crée pas d’information : elle la répartit. Chaque copie perd des sections différentes, donc l’union des copies couvre le message entier — à condition que les pertes soient indépendantes. C’est le principe du RAID, des codes correcteurs et des sauvegardes croisées, et sa limite est la même partout : une cause commune de destruction annule le bénéfice des copies." },
  { id:"FL-18", mod:"Miscellaneous", t:"CAP_SYS_FLUFFY : la finale dans l’arbre creux", sub:"Module Miscellaneous, défis 04 et 05 : Foxfire Fragments — verrouillé sur le site — puis CAP_SYS_FLUFFY, la finale du dojo, avec Pip.",
    read:["Avant la finale, un défi verrouillé : Foxfire Fragments. Titre visible, description masquée — son thème ne peut qu’être inféré : le titre évoque des fragments à réassembler, dans la continuité de la chaîne des copies endommagées, mais c’est une lecture du titre, signalée comme telle, pas un contenu du site. Le dojo se termine donc, pour ce qu’on peut en lire, sur le défi 05 : CAP_SYS_FLUFFY.",
      "Des jours passent. Fluffy rapporte chaque matin des pièces trouvées — bouts de métal, fils, outils — et s’installe dans un arbre creux portant son nom gravé dans l’écorce. L’arbre ne demande rien, n’inspecte rien, ne vérifie pas si c’est une bonne idée : il fait confiance à celui qui a revendiqué l’endroit. Un soir, Fluffy rapporte quelque chose construit entièrement par lui et le pose près du terminal de la clairière. Le terminal l’exécute. Sans question, sans avertissement. Mais surtout : il l’exécute comme quelque chose que Fluffy n’est pas — avec plus de poids, plus de portée. Ce qui sort de cet espace arrive avec un tampon que le système reconnaît comme le sien. L’écran affiche un nom qui n’est pas celui de Fluffy. Dans le noir, la visière de Pip brille en bleu électrique.",
      "Le concept de la finale est l’élévation de privilèges par les capabilities Linux — le nom du défi cite la famille CAP_SYS_*, les capabilities d’administration système. Le mécanisme mis en scène : un programme lancé depuis un contexte de confiance hérite de droits que son auteur n’a pas — l’équivalent des binaires setuid ou dotés de capabilities, qui s’exécutent avec l’identité et les pouvoirs d’un autre. Toute la quête se referme sur la leçon la plus transversale de pwn.college : les privilèges ne tiennent pas à qui lance le programme, mais au contexte qui l’exécute. Côté défense : inventorier les binaires privilégiés, n’accorder que les capabilities strictement nécessaires, et se méfier de tout espace « de confiance » qui exécute sans vérifier — un arbre creux, un dossier partagé, un service trop permissif. Fluffy visait la ceinture bleue ; il repart avec la question qui protège tous les systèmes : qui, exactement, a le droit d’exécuter quoi, et avec les droits de qui ?"],
    term:"contexte de confiance + programme ordinaire = privilèges d’un autre\n<span class=\"tdim\">La finale du dojo : le terminal exécute l’outil de Fluffy « comme quelque chose que Fluffy n’est pas ». C’est le principe des exécutions privilégiées — setuid et capabilities CAP_SYS_*.</span>",
    ex:{ type:"qcm", q:"Dans la finale, pourquoi le programme de Fluffy s’exécute-t-il avec plus de droits que Fluffy lui-même ?",
      opts:["Parce que Fluffy a deviné le mot de passe du terminal", "Parce qu’il est lancé depuis un contexte de confiance qui lui confère des privilèges supérieurs — le mécanisme des capabilities (et des binaires setuid) : le système lui prête une identité plus puissante que la sienne", "Parce que Pip a piraté le terminal pendant la nuit"], ok:1 },
    why:"Aucun mot de passe n’est forcé, aucun terminal n’est piraté : le programme hérite ses droits de son contexte d’exécution, pas de son auteur. C’est le principe des exécutions privilégiées sous Linux — binaires setuid et capabilities de la famille CAP_SYS_* — et la raison pour laquelle l’audit des programmes privilégiés et des espaces « de confiance » est un pilier de la défense : tout ce qui s’y dépose peut s’exécuter avec les droits d’un autre." }
];
